"use strict";(self.webpackChunkdocusaurus=self.webpackChunkdocusaurus||[]).push([["9455"],{26320(e,t,n){n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>r,default:()=>h,frontMatter:()=>s,metadata:()=>a,toc:()=>c});var a=n(8068),i=n(74848),o=n(28453);let s={title:"What changes when organisations contribute into a shared model",date:"2026-04-29 18:35:00 +1000",slug:"/2026/04/29/what-changes-when-organisations-contribute-into-a-shared-model",description:"The real shift is not getting people to collaborate more. It is getting different roles, tools, and artifacts to contribute into a shared semantic model that preserves reuse, traceability, and organisational coherence."},r,l={authorsImageUrls:[]},c=[{value:"What changes in practice",id:"what-changes-in-practice",level:2},{value:"Strategy becomes reusable instead of rhetorical",id:"strategy-becomes-reusable-instead-of-rhetorical",level:3},{value:"Catalogs stop competing and start aligning",id:"catalogs-stop-competing-and-start-aligning",level:3},{value:"Performance becomes evidence, not just reporting",id:"performance-becomes-evidence-not-just-reporting",level:3},{value:"Governance artifacts become live, not decorative",id:"governance-artifacts-become-live-not-decorative",level:3},{value:"AI becomes more useful and less destabilising",id:"ai-becomes-more-useful-and-less-destabilising",level:3},{value:"What does not change",id:"what-does-not-change",level:2},{value:"The deeper implication",id:"the-deeper-implication",level:2},{value:"Related reading",id:"related-reading",level:2}];function d(e){let t={a:"a",h2:"h2",h3:"h3",li:"li",p:"p",strong:"strong",ul:"ul",...(0,o.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.p,{children:"If the first problem is fragmentation, the next question is obvious:\nwhat actually changes when an organisation stops treating collaboration as the exchange of disconnected artifacts and starts treating it as contribution into a shared model?"}),"\n",(0,i.jsx)(t.p,{children:"A lot changes."}),"\n",(0,i.jsx)(t.p,{children:"Not because the organisation suddenly becomes perfectly aligned.\nNot because everyone adopts one tool.\nNot because all ambiguity disappears."}),"\n",(0,i.jsx)(t.p,{children:"But because meaning begins to accumulate instead of being repeatedly recreated."}),"\n","\n",(0,i.jsx)(t.p,{children:"In most organisations today, strategy lives in one place, service understanding in another, architecture in another, operational evidence somewhere else, and process knowledge somewhere else again. Each of these artifacts can be useful. But they are usually useful within their own boundary more than across boundaries."}),"\n",(0,i.jsx)(t.p,{children:"A shared model changes that by giving those artifacts somewhere common to land."}),"\n",(0,i.jsx)(t.p,{children:"The shift is not from \u201Cmany artifacts\u201D to \u201Cone artifact\u201D.\nIt is from many disconnected surfaces to many contribution surfaces feeding a shared semantic backbone."}),"\n",(0,i.jsx)(t.p,{children:"That distinction matters."}),"\n",(0,i.jsx)(t.p,{children:"When people hear \u201Cshared model\u201D, they often imagine a central architecture diagram, a master data schema, or a governance repository that a few specialists maintain while everyone else ignores it. That is not the model worth aiming for."}),"\n",(0,i.jsx)(t.p,{children:"A stronger model allows different people to keep working through the surfaces that make sense for them:"}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsx)(t.li,{children:"leaders through mission, vision, and strategic framing"}),"\n",(0,i.jsx)(t.li,{children:"analysts through scenarios, process views, and planning structures"}),"\n",(0,i.jsx)(t.li,{children:"architects through service, application, deployment, and integration structures"}),"\n",(0,i.jsx)(t.li,{children:"operations through runtime, performance, and incident evidence"}),"\n",(0,i.jsx)(t.li,{children:"developers through interfaces, implementation detail, and technical change"}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:"The important difference is that these surfaces no longer remain isolated truth islands.\nThey become contribution points into something structurally shared."}),"\n",(0,i.jsx)(t.h2,{id:"what-changes-in-practice",children:"What changes in practice"}),"\n",(0,i.jsx)(t.h3,{id:"strategy-becomes-reusable-instead-of-rhetorical",children:"Strategy becomes reusable instead of rhetorical"}),"\n",(0,i.jsx)(t.p,{children:"In many organisations, strategy is visible but weakly reusable.\nIt is announced in slide decks, town halls, or planning documents, but it rarely becomes part of the structural logic of how services, workflows, systems, and metrics are interpreted."}),"\n",(0,i.jsx)(t.p,{children:"In a shared model, mission, vision, strategy, and goals become reusable semantic structures.\nThey can be connected to capabilities, service boundaries, decisions, controls, risks, and performance signals."}),"\n",(0,i.jsx)(t.p,{children:"That means strategy is no longer just something the organisation says.\nIt becomes something the organisation can structurally reference."}),"\n",(0,i.jsx)(t.h3,{id:"catalogs-stop-competing-and-start-aligning",children:"Catalogs stop competing and start aligning"}),"\n",(0,i.jsx)(t.p,{children:"Most enterprises have many catalogs: products, services, APIs, data assets, applications, infrastructure components, controls, or capabilities."}),"\n",(0,i.jsx)(t.p,{children:"These catalogs often overlap because they are each trying to describe part of the same reality from different angles. But without a shared model, they drift into parallel but incompatible definitions."}),"\n",(0,i.jsx)(t.p,{children:"A stronger contribution model does not force them into one flattened taxonomy.\nInstead, it allows them to remain distinct contribution surfaces while linking them through shared semantics."}),"\n",(0,i.jsx)(t.p,{children:"That lets product, service, architectural, and technical views coexist without becoming separate worlds."}),"\n",(0,i.jsx)(t.h3,{id:"performance-becomes-evidence-not-just-reporting",children:"Performance becomes evidence, not just reporting"}),"\n",(0,i.jsx)(t.p,{children:"Performance data is often trapped inside the reporting surface that produced it.\nService performance sits with service teams. Infrastructure performance sits with operations. Workload performance sits with planners. Business outcome reporting sits somewhere else again."}),"\n",(0,i.jsx)(t.p,{children:"In a shared model, these stop being just local reports.\nThey become evidence surfaces attached to common structures."}),"\n",(0,i.jsx)(t.p,{children:"That means performance can be interpreted in relation to:"}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsx)(t.li,{children:"the service it affects"}),"\n",(0,i.jsx)(t.li,{children:"the application or deployment structure behind it"}),"\n",(0,i.jsx)(t.li,{children:"the strategic objective it threatens or supports"}),"\n",(0,i.jsx)(t.li,{children:"the control or risk posture connected to it"}),"\n",(0,i.jsx)(t.li,{children:"the accountable roles around it"}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:"This is a major shift from dashboard consumption to shared organisational sense-making."}),"\n",(0,i.jsx)(t.h3,{id:"governance-artifacts-become-live-not-decorative",children:"Governance artifacts become live, not decorative"}),"\n",(0,i.jsx)(t.p,{children:"Frameworks, policies, accountability structures, and leadership models are often treated as if they exist outside operational reality.\nThey sit in policy shelves, governance decks, and review packs."}),"\n",(0,i.jsx)(t.p,{children:"A shared model lets these become live contribution surfaces.\nAn accountability framework can connect to roles, decisions, obligations, and review structures. A leadership framework can connect to strategy, intervention logic, prioritisation, and performance interpretation."}),"\n",(0,i.jsx)(t.p,{children:"That turns governance from something that comments on the system into something that structurally participates in it."}),"\n",(0,i.jsx)(t.h3,{id:"ai-becomes-more-useful-and-less-destabilising",children:"AI becomes more useful and less destabilising"}),"\n",(0,i.jsx)(t.p,{children:"This may become one of the most important effects."}),"\n",(0,i.jsx)(t.p,{children:"When AI operates over disconnected artifacts, it tends to amplify local interpretation.\nIt can still be useful, but its usefulness is bounded by the fragmentation of the environment it is working in."}),"\n",(0,i.jsx)(t.p,{children:"When AI operates in a model where contribution surfaces feed a shared semantic backbone, its role changes. It can help classify, connect, summarise, compare, surface missing context, and suggest useful reuse paths with much stronger grounding."}),"\n",(0,i.jsx)(t.p,{children:"That does not make AI magically correct.\nBut it does make it much less dependent on free-floating local context."}),"\n",(0,i.jsx)(t.h2,{id:"what-does-not-change",children:"What does not change"}),"\n",(0,i.jsxs)(t.p,{children:["It is also important to say what this model does ",(0,i.jsx)(t.strong,{children:"not"})," do."]}),"\n",(0,i.jsx)(t.p,{children:"It does not remove the need for judgement.\nIt does not eliminate politics.\nIt does not make organisations perfectly rational.\nIt does not remove the need for role-specific tools or views.\nIt does not mean every concept will be modeled fully from the start."}),"\n",(0,i.jsx)(t.p,{children:"What it changes is the direction of accumulation."}),"\n",(0,i.jsx)(t.p,{children:"Without a shared model, meaning fragments by default and has to be repaired after the fact.\nWith a shared model, meaning has a place to accumulate, connect, and become reusable over time."}),"\n",(0,i.jsx)(t.p,{children:"That is a very different operating condition."}),"\n",(0,i.jsx)(t.h2,{id:"the-deeper-implication",children:"The deeper implication"}),"\n",(0,i.jsx)(t.p,{children:"The deeper implication is that collaboration itself has to be re-understood."}),"\n",(0,i.jsx)(t.p,{children:"Collaboration is not only conversation.\nIt is not only coordination.\nIt is not only co-authoring documents."}),"\n",(0,i.jsx)(t.p,{children:"At an organisational level, collaboration should mean that different roles can contribute from their own context into a shared semantic structure that outlives the moment of contribution."}),"\n",(0,i.jsx)(t.p,{children:"That is why the collaboration model matters so much.\nIt is really a contribution model."}),"\n",(0,i.jsx)(t.p,{children:"And in an AI-enabled organisation, that may become one of the most important distinctions of all."}),"\n",(0,i.jsx)(t.p,{children:"The organisations that do best will not simply be the ones that generate the most artifacts, reports, plans, or AI outputs.\nThey will be the ones that can make more of that output land in a form that remains connected, traceable, reusable, and structurally meaningful."}),"\n",(0,i.jsx)(t.p,{children:"That is what changes when contribution starts feeding a shared model."}),"\n",(0,i.jsx)(t.h2,{id:"related-reading",children:"Related reading"}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsx)(t.li,{children:(0,i.jsx)(t.a,{href:"/blog/2026/04/29/why-organisations-keep-recreating-the-same-knowledge-and-why-ai-will-make-it-worse",children:"Why organisations keep recreating the same knowledge \u2014 and why AI will make it worse"})}),"\n",(0,i.jsx)(t.li,{children:(0,i.jsx)(t.a,{href:"/knowledgeontology/model/collaboration",children:"Model Collaboration"})}),"\n",(0,i.jsx)(t.li,{children:(0,i.jsx)(t.a,{href:"/blog/2015/06/24/what-a-shared-organisational-model-is-actually-for",children:"What a shared organisational model is actually for"})}),"\n",(0,i.jsx)(t.li,{children:(0,i.jsx)(t.a,{href:"/blog/2026/04/23/how-an-organisation-would-build-its-own-knowledgefund",children:"How an organisation would build its own KnowledgeFund"})}),"\n"]})]})}function h(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},28453(e,t,n){n.d(t,{R:()=>s,x:()=>r});var a=n(96540);let i={},o=a.createContext(i);function s(e){let t=a.useContext(o);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),a.createElement(o.Provider,{value:t},e.children)}},8068(e){e.exports=JSON.parse('{"permalink":"/blog/2026/04/29/what-changes-when-organisations-contribute-into-a-shared-model","source":"@site/blog/2026-04-29-what-changes-when-organisations-contribute-into-a-shared-model.md","title":"What changes when organisations contribute into a shared model","description":"The real shift is not getting people to collaborate more. It is getting different roles, tools, and artifacts to contribute into a shared semantic model that preserves reuse, traceability, and organisational coherence.","date":"2026-04-29T18:35:00.000Z","tags":[],"readingTime":5.46,"hasTruncateMarker":true,"authors":[],"frontMatter":{"title":"What changes when organisations contribute into a shared model","date":"2026-04-29 18:35:00 +1000","slug":"/2026/04/29/what-changes-when-organisations-contribute-into-a-shared-model","description":"The real shift is not getting people to collaborate more. It is getting different roles, tools, and artifacts to contribute into a shared semantic model that preserves reuse, traceability, and organisational coherence."},"unlisted":false,"prevItem":{"title":"Why a shared core needs tailored experiences","permalink":"/blog/2026/04/29/why-a-shared-core-needs-tailored-experiences"},"nextItem":{"title":"Why organisations keep recreating the same knowledge \u2014 and why AI will make it worse","permalink":"/blog/2026/04/29/why-organisations-keep-recreating-the-same-knowledge-and-why-ai-will-make-it-worse"}}')}}]);